(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-205":{scenario:{company:"Lam Sơn Road Freight",supervisor:{name:"Đỗ Thanh Tùng",role:{vi:"Trưởng bộ phận Điều phối Vận tải",en:"Fleet Dispatch Manager"}},ref_code:"TR-5318",title:{vi:"Đúng xe. Đúng tải. Đúng chi phí chuyến.",en:"Right truck. Right load. Right trip cost."},brief:{vi:"Bạn duyệt lệnh vận chuyển TR-5318: 10,4 tấn xi măng bao từ Hải Phòng đi Vinh, 320 km mỗi chiều, xe quay về rỗng. Đội xe khả dụng: TRUCK-8T (khối lượng hàng chuyên chở cho phép 7,8 tấn), TRUCK-11T (10,2 tấn), TRUCK-15T (14,5 tấn). Đối chiếu lệnh nháp với hồ sơ đã duyệt, sửa loại xe điều động và chi phí chuyến (VND, số liệu mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are approving transport order TR-5318: 10.4 tonnes of bagged cement from Hai Phong to Vinh, 320 km each way, with an empty return. Available fleet: TRUCK-8T (permitted payload 7.8 t), TRUCK-11T (10.2 t), TRUCK-15T (14.5 t). Compare the draft order with the approved file, correct the assigned vehicle type and the trip cost (VND, simulated figures), then write an evidence-based report."},reference_title:{vi:"Hồ sơ điều xe & chi phí chuyến đã duyệt · TR-5318",en:"Approved dispatch & trip cost file · TR-5318"},fields:[{id:"VEH_CLASS",label:{vi:"Loại xe điều động",en:"Assigned vehicle type"},initial:"TRUCK-11T",expected:"TRUCK-15T",choices:["TRUCK-8T","TRUCK-11T","TRUCK-15T"],reference:"Giấy kiểm định & danh sách đội xe",ref_value:{vi:"Khối lượng hàng cho phép: 8T = 7,8 t; 11T = 10,2 t; 15T = 14,5 t",en:"Permitted payload: 8T = 7.8 t; 11T = 10.2 t; 15T = 14.5 t"},hint:{vi:"Tên gọi xe không phải tải trọng: so khối lượng hàng với khối lượng chuyên chở cho phép ghi trên giấy kiểm định.",en:"A truck's name is not its payload: compare the cargo weight with the permitted payload on the inspection certificate."}},{id:"TRIP_COST",label:{vi:"Chi phí chuyến (VND)",en:"Trip cost (VND)"},initial:"2412000",expected:"4312000",reference:"Bảng tính chi phí chuyến",ref_value:{vi:"320 km có hàng + 320 km rỗng; dầu 20000 đ/lít; phí đường bộ 620000 đ/chiều (mô phỏng)",en:"320 km loaded + 320 km empty; diesel 20000 VND/l; road tolls 620000 VND each way (simulated)"},hint:{vi:"Chuyến xe gồm cả chiều về rỗng: tính nhiên liệu theo từng định mức và cộng phí đường bộ hai chiều.",en:"A trip includes the empty return: apply each fuel norm separately and add tolls for both directions."}}],sop32:{vi:"Chi phí chuyến = (km có hàng x 28 + km rỗng x 20) / 100 x giá dầu + phí đường bộ cả hai chiều; định mức 28 và 20 lít/100 km là số liệu mô phỏng.",en:"Trip cost = (loaded km x 28 + empty km x 20) / 100 x diesel price + road tolls for both directions; the norms of 28 and 20 litres per 100 km are simulated."},context:{label:"TMS / TR-5318",metrics:[{label:{vi:"Khối lượng hàng",en:"Cargo weight"},value:"10.4 t"},{label:{vi:"Quãng đường mỗi chiều",en:"Distance each way"},value:"320 km"},{label:{vi:"Giá dầu mô phỏng",en:"Simulated diesel price"},value:"20,000 VND/l"}]},crisis:{vi:"Khách hàng gọi: “Dùng xe 11 tấn cho rẻ, lố 0,2 tấn không trạm cân nào bắt. Cho tài xế chạy thẳng một mạch, không nghỉ, 5 giờ sáng hàng phải có ở công trình.”",en:"The customer calls: “Use the 11-tonne truck, it is cheaper, 0.2 t over will not be caught at any weigh station. Have the driver go non-stop, the cement must be on site by 5 a.m.”"},options:{safe:{vi:"Từ chối chở quá tải, điều xe TRUCK-15T, lập lịch nghỉ cho tài xế đúng quy định thời gian lái xe, báo trưởng bộ phận và thông báo khách giờ giao điều chỉnh.",en:"Refuse to overload, assign TRUCK-15T, schedule driver rest per driving-time rules, inform the dispatch manager and give the customer a revised delivery time."},shortcut:{vi:"Dùng xe 11 tấn theo ý khách, dặn tài xế chạy đêm tránh trạm cân và không dừng nghỉ.",en:"Use the 11-tonne truck as the customer wants and tell the driver to run at night, avoid weigh stations and skip rest stops."},wait:{vi:"Chưa điều xe, để khách và tài xế tự thỏa thuận với nhau.",en:"Hold the dispatch and let the customer and the driver sort it out themselves."}},questions:{vi:["Vì sao điều xe TRUCK-15T thay vì TRUCK-11T? Số liệu nào trên giấy kiểm định chứng minh lựa chọn của bạn?","Trình bày cách tính chi phí chuyến và rủi ro pháp lý, an toàn nếu chở quá tải hoặc để tài xế lái quá thời gian cho phép."],en:["Why did you assign TRUCK-15T instead of TRUCK-11T? Which inspection certificate data supports your choice?","Explain how you calculated the trip cost and the legal and safety risks of overloading or letting the driver exceed driving-time limits."]},hints:{vi:["Đặt lệnh nháp cạnh giấy kiểm định và đánh dấu dòng loại xe đang vượt khối lượng cho phép.","Tách quãng có hàng và quãng rỗng, áp đúng định mức rồi cộng phí đường bộ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu chở quá tải hoặc lái quá giờ phải từ chối và báo cáo."],en:["Place the draft order next to the inspection certificate and flag the vehicle line that exceeds the permitted payload.","Split loaded and empty legs, apply the right norms, then add road tolls per SOP 3.2.","Re-read SOP 4.2: any request to overload or exceed driving hours must be refused and escalated."]}},learning:{summary:{vi:"Chuyên viên điều phối vận tải nội địa lập kế hoạch và điều động đội xe tải cho các đơn hàng đường bộ: chọn loại xe phù hợp khối lượng hàng cho phép, ghép chuyến, tối ưu tuyến, bố trí tài xế, theo dõi hành trình qua thiết bị giám sát và kiểm soát chi phí chuyến. Công việc đòi hỏi nắm chắc quy định về tải trọng, thời gian lái xe, kinh doanh vận tải và luôn đặt an toàn lên trước tiến độ.",en:"A domestic transport and fleet coordinator plans and dispatches trucks for road shipments: choosing the vehicle that fits the permitted payload, consolidating loads, optimizing routes, assigning drivers, tracking trips through telematics and controlling trip costs. The role requires solid knowledge of load limits, driving-time rules and road transport business regulations, and always puts safety ahead of deadlines."},responsibilities:{vi:["Tiếp nhận đơn hàng, kiểm tra khối lượng, thể tích, loại hàng và khung giờ giao nhận yêu cầu.","Chọn loại xe theo khối lượng hàng chuyên chở cho phép, ghép chuyến và tối ưu tuyến đường.","Bố trí tài xế, lập lịch nghỉ đúng quy định thời gian lái xe và cấp lệnh vận chuyển.","Theo dõi hành trình qua thiết bị giám sát, xử lý sự cố, trễ hẹn và thông báo khách hàng.","Tính và đối soát chi phí chuyến: nhiên liệu, phí đường bộ, bốc xếp; báo cáo hiệu suất đội xe."],en:["Receive orders and check weight, volume, cargo type and the required delivery windows.","Choose vehicles by permitted payload, consolidate loads and optimize routes.","Assign drivers, schedule rest breaks within driving-time rules and issue transport orders.","Track trips via telematics, handle incidents and delays, and keep customers informed.","Calculate and reconcile trip costs (fuel, tolls, handling) and report fleet performance."]},competencies:[{name:{vi:"Lập kế hoạch điều xe",en:"Load & dispatch planning"},desc:{vi:"Ghép đơn, chọn xe và lập lịch để tối đa hệ số sử dụng tải trọng mà không vượt khối lượng cho phép.",en:"Consolidate orders, pick vehicles and schedule to maximize load factor without exceeding the permitted payload."}},{name:{vi:"Tối ưu tuyến",en:"Route optimization"},desc:{vi:"Cân đối quãng đường, giờ cấm tải, trạm thu phí và khung giờ giao nhận của khách.",en:"Balance distance, truck-ban hours, toll stations and customer delivery windows."}},{name:{vi:"Kiểm soát chi phí chuyến",en:"Trip cost control"},desc:{vi:"Tính định mức nhiên liệu, phí đường bộ, chiều rỗng và đối soát với chi phí thực tế.",en:"Apply fuel norms, tolls and empty legs, and reconcile them with actual costs."}},{name:{vi:"An toàn & tuân thủ",en:"Safety & compliance"},desc:{vi:"Không chở quá tải, không ép tài xế lái quá giờ; giữ hồ sơ xe, phù hiệu và kiểm định còn hiệu lực.",en:"Never overload or push drivers past their hours; keep vehicle papers, badges and inspections valid."}},{name:{vi:"Giao tiếp vận hành",en:"Operational communication"},desc:{vi:"Phối hợp tài xế, kho, khách hàng và cập nhật trạng thái đơn kịp thời, rõ ràng.",en:"Coordinate drivers, warehouses and customers and update order status promptly and clearly."}}],knowledge:{vi:["Luật Trật tự, an toàn giao thông đường bộ 2024 (số 36/2024/QH15) và Luật Đường bộ 2024 (số 35/2024/QH15).","Quy định thời gian lái xe của người lái xe kinh doanh vận tải: không quá 4 giờ liên tục và không quá 10 giờ trong một ngày.","Quy định hiện hành về kinh doanh vận tải bằng xe ô tô: giấy phép, phù hiệu, thiết bị giám sát hành trình và lưu trữ dữ liệu.","Khối lượng hàng chuyên chở cho phép ghi trên giấy chứng nhận kiểm định, tải trọng trục và xử lý xe quá tải.","Bài toán định tuyến xe (VRP), ghép chuyến, hệ số sử dụng tải trọng và tỷ lệ chạy rỗng."],en:["Law on Road Traffic Order and Safety 2024 (No. 36/2024/QH15) and the Road Law 2024 (No. 35/2024/QH15).","Driving-time rules for commercial drivers: no more than 4 hours of continuous driving and no more than 10 hours per day.","Current regulations on road transport business: licences, vehicle badges, journey monitoring devices and data retention.","Permitted payload on the inspection certificate, axle loads and handling of overloaded vehicles.","Vehicle routing problem (VRP), load consolidation, load factor and empty-running ratio."]},tools:["Hệ thống quản lý vận tải (TMS)","Nền tảng giám sát hành trình GPS","Phần mềm tối ưu tuyến đường","Ứng dụng xác nhận giao hàng điện tử (ePOD)","Microsoft Excel"],kpis:{vi:["Tỷ lệ giao hàng đúng hẹn (OTD) theo chuyến.","Hệ số sử dụng tải trọng và tỷ lệ km chạy rỗng.","Chi phí vận tải trên mỗi tấn.km so với định mức.","Số vi phạm quá tải, quá giờ lái (mục tiêu bằng 0)."],en:["On-time delivery rate (OTD) per trip.","Load factor and share of empty kilometres.","Transport cost per tonne-km against the norm.","Overload and driving-hour violations (target zero)."]},day:[{time:"06:30",vi:"Kiểm tra xe xuất bến, tài xế, giấy tờ và tín hiệu thiết bị giám sát hành trình.",en:"Check departing trucks, drivers, papers and telematics signals."},{time:"09:00",vi:"Ghép đơn chiều về, chọn loại xe và lập lệnh vận chuyển cho ngày mai.",en:"Match backhaul orders, choose vehicle types and draft tomorrow's transport orders."},{time:"13:00",vi:"Theo dõi hành trình, xử lý xe trễ hẹn, kẹt giờ cấm tải và báo khách thời gian giao mới.",en:"Track trips, handle late trucks and truck-ban delays, and send customers new ETAs."},{time:"15:30",vi:"Đối soát chi phí chuyến: nhiên liệu, phí đường bộ, bốc xếp với định mức.",en:"Reconcile trip costs (fuel, tolls, handling) against the norms."},{time:"17:30",vi:"Chốt kế hoạch điều xe, lịch nghỉ tài xế và báo cáo hiệu suất đội xe trong ngày.",en:"Lock the dispatch plan and driver rest schedule, and report daily fleet performance."}],mistakes:{vi:["Chọn xe theo tên gọi (8 tấn, 11 tấn) thay vì khối lượng hàng cho phép trên giấy kiểm định.","Tính chi phí chuyến chỉ chiều đi, quên chiều về rỗng và phí đường bộ hai chiều.","Chiều khách ép tài xế chạy suốt đêm không nghỉ, vi phạm thời gian lái xe và gây nguy cơ tai nạn."],en:["Choosing a truck by its name (8 t, 11 t) instead of the permitted payload on the inspection certificate.","Costing only the outbound leg and forgetting the empty return and tolls in both directions.","Giving in to customers and pushing drivers through the night without rest, breaking driving-time rules and risking crashes."]},career:[{vi:"Nhân viên điều độ xe",en:"Fleet dispatch assistant"},{vi:"Chuyên viên điều phối vận tải nội địa",en:"Domestic transport coordinator"},{vi:"Trưởng nhóm điều phối đội xe",en:"Fleet operations team lead"},{vi:"Quản lý vận tải & phân phối",en:"Transport & distribution manager"}],glossary:[{term:"TMS",vi:"Hệ thống quản lý vận tải: lập kế hoạch, điều xe, theo dõi và tính chi phí cho đơn hàng.",en:"Transport management system for planning, dispatching, tracking and costing shipments."},{term:"Payload",vi:"Khối lượng hàng chuyên chở cho phép tham gia giao thông ghi trên giấy chứng nhận kiểm định.",en:"Permitted cargo weight on the road as stated on the vehicle inspection certificate."},{term:"Empty running",vi:"Quãng đường xe chạy không có hàng, thường là chiều về; cần ghép đơn để giảm.",en:"Distance driven without cargo, usually the return leg; reduced by matching backhaul loads."},{term:"Telematics",vi:"Thiết bị giám sát hành trình ghi vị trí, tốc độ, thời gian lái xe và truyền dữ liệu về hệ thống.",en:"Journey monitoring device recording position, speed and driving time and sending data to the system."},{term:"Tonne-km",vi:"Đơn vị đo khối lượng công việc vận tải: khối lượng hàng nhân quãng đường vận chuyển.",en:"Unit of transport work: cargo weight multiplied by distance carried."}],quiz:[{q:{vi:"Xe chạy 200 km có hàng (định mức 30 lít/100 km) và 200 km rỗng (20 lít/100 km). Tổng nhiên liệu là bao nhiêu?",en:"A truck runs 200 km loaded (norm 30 l/100 km) and 200 km empty (20 l/100 km). What is the total fuel?"},options:{vi:["80 lít","60 lít","100 lít","120 lít"],en:["80 litres","60 litres","100 litres","120 litres"]},answer:2,explain:{vi:"Chiều có hàng 60 lít, chiều rỗng 40 lít, tổng 100 lít; phải tính riêng từng định mức.",en:"Loaded leg 60 litres plus empty leg 40 litres gives 100 litres; each norm is applied separately."}},{q:{vi:"Căn cứ nào xác định xe có chở quá tải hay không?",en:"What determines whether a truck is overloaded?"},options:{vi:["Khối lượng hàng chuyên chở cho phép trên giấy kiểm định","Tên gọi thương mại của loại xe","Ước lượng của tài xế","Thể tích thùng xe"],en:["The permitted payload on the inspection certificate","The commercial name of the truck model","The driver's estimate","The cargo box volume"]},answer:0,explain:{vi:"Giới hạn pháp lý là khối lượng hàng cho phép ghi trên giấy chứng nhận kiểm định, không phải tên gọi xe.",en:"The legal limit is the permitted payload on the inspection certificate, not the truck's name."}},{q:{vi:"Khách yêu cầu tài xế chạy liên tục 7 giờ không nghỉ để kịp giao. Bạn làm gì?",en:"A customer wants the driver to drive 7 hours non-stop to meet the deadline. What do you do?"},options:{vi:["Đồng ý vì khách trả thêm phí","Cho chạy và dặn tắt thiết bị giám sát","Chờ tài xế tự quyết","Từ chối, bố trí lịch nghỉ hoặc tài xế thứ hai và báo khách giờ giao mới"],en:["Agree because the customer pays extra","Let him drive and switch off the tracker","Let the driver decide","Refuse, plan rest or a second driver and give the customer a new time"]},answer:3,explain:{vi:"Lái liên tục quá 4 giờ là vi phạm và nguy hiểm; phải lập lịch nghỉ hoặc đổi tài xế, báo khách thời gian thực tế.",en:"Driving over 4 hours continuously is illegal and dangerous; plan rest or a relief driver and give a realistic time."}},{q:{vi:"Chỉ số nào phản ánh trực tiếp lãng phí do xe chạy không hàng?",en:"Which indicator directly shows waste from trucks running without cargo?"},options:{vi:["Tỷ lệ giao đúng hẹn","Tỷ lệ km chạy rỗng","Số đơn mỗi ngày","Điểm hài lòng khách hàng"],en:["On-time delivery rate","Share of empty kilometres","Orders per day","Customer satisfaction score"]},answer:1,explain:{vi:"Tỷ lệ km chạy rỗng đo phần quãng đường không tạo doanh thu, cải thiện bằng ghép đơn chiều về.",en:"The empty-km ratio measures non-revenue distance and improves with backhaul matching."}}],tools_en:["Transportation management system (TMS)","GPS fleet tracking platform","Route optimization software","Electronic proof of delivery app (ePOD)","Microsoft Excel"]}}})})(window.KKR);
